    The Finalize function in nsSimpleMimeConverterStub.cpp was missing a call to the superclass finalize.

    Differential Revision: https://phabricator.services.mozilla.com/D298561

diff --git a/mailnews/mime/src/nsSimpleMimeConverterStub.cpp b/mailnews/mime/src/nsSimpleMimeConverterStub.cpp
index 3d99aa16260..b822abdfbdd 100644
--- a/mailnews/mime/src/nsSimpleMimeConverterStub.cpp
+++ b/mailnews/mime/src/nsSimpleMimeConverterStub.cpp
@@ -135,6 +135,8 @@ static void Finalize(MimeObject* obj) {
   MimeSimpleStub* ssobj = (MimeSimpleStub*)obj;
   ssobj->innerScriptable = nullptr;
   delete ssobj->buffer;
+  ssobj->buffer = nullptr;
+  ((MimeObjectClass*)MIME_GetmimeInlineTextClass())->finalize(obj);
 }

